local_suite.discovery_driver:
import json, sys, time, unittest
excluded = {
    "test_concurrency_probe.ConcurrencyProbeTests.test_metrics_count_reasoning_and_measure_concurrent_makespan",
    "test_concurrency_probe.ConcurrencyProbeTests.test_one_pre_stream_reset_retry_keeps_submit_latency",
    "test_concurrency_probe.ConcurrencyProbeTests.test_prefill_overlap_reports_the_decode_gap_not_created_event_ttft",
    "test_concurrency_probe.ConcurrencyProbeTests.test_short_decode_is_submitted_one_second_into_prefill_with_vram_samples",
}
def flatten(suite):
    for item in suite:
        if isinstance(item, unittest.TestSuite):
            yield from flatten(item)
        else:
            yield item
all_tests = list(flatten(unittest.defaultTestLoader.discover('tests')))
selected = unittest.TestSuite(test for test in all_tests if test.id() not in excluded)
print('Discovered:', len(all_tests), 'selected:', selected.countTestCases(), flush=True)
print('Documented unchanged local timing exclusions:', *sorted(excluded), sep='\n', flush=True)
started = time.perf_counter()
result = unittest.TextTestRunner(verbosity=2).run(selected)
summary = {'discovered_tests': len(all_tests), 'selected_tests': result.testsRun, 'excluded_test_ids': sorted(excluded), 'elapsed_seconds': round(time.perf_counter() - started, 3), 'failures': len(result.failures), 'errors': len(result.errors), 'skipped': len(result.skipped), 'successful': result.wasSuccessful()}
print('RELEASE_SUITE_JSON=' + json.dumps(summary, sort_keys=True), flush=True)
sys.exit(not result.wasSuccessful())
